export default function({$,$$,K,html,raw,put,S,TRIPS,TOWNS,opts}){const P={checkout(){const o=S.get('order');if(!o){location='index.html';return}
put($('#sum'),html`<b>${o.trip.op}</b><br>${o.q.f} → ${o.q.t}, ${o.q.d} · ${o.trip.dep}<br>Seats ${o.seats.join(', ')}<div class="tot">${K(o.total)}</div><span class="mu">Includes K 20 booking fee</span>`);$('#amt').textContent=K(o.total);const show=x=>{$$('[data-st]').forEach(p=>p.classList.toggle('hid',p.dataset.st!=x))};$('#pay').onsubmit=e=>{e.preventDefault();show('p');setTimeout(()=>{if($('#fail').checked)return show('f');o.ref='ZM'+Math.random().toString(36).slice(2,8).toUpperCase();S.set('order',o);show('s');setTimeout(()=>location='ticket.html',1200)},1800)};$('#retry').onclick=()=>{$('#fail').checked=false;show('')}}
};return P.checkout;}